import { ChangeDetectionStrategy, Component, computed, inject, linkedSignal } from '@angular/core';
import { ActivityHealthReport, WeekRange } from '../../core/models';
import { AccountSummary } from './components/account-summary';
import { DashboardFilters } from './components/dashboard-filters';
import { LocationTable } from './components/location-table';
import { DashboardState } from './dashboard-state';
import { formatCalendarDay, sundayOfWeek } from './week';

@Component({
  selector: 'app-dashboard-page',
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [AccountSummary, DashboardFilters, LocationTable],
  providers: [DashboardState],
  template: `
    <main>
      <h1>Activity health</h1>

      <app-dashboard-filters
        [accounts]="state.accounts()"
        [accountId]="state.accountId()"
        [week]="stepperWeek()"
        [earliestWeek]="lastLoadedReport()?.earliestWeek ?? null"
        [latestCompleteWeek]="lastLoadedReport()?.latestCompleteWeek ?? null"
        [eventType]="state.eventType()"
        (accountSelected)="state.selectAccount($event)"
        (weekSelected)="state.selectWeek($event)"
        (eventTypeSelected)="state.selectEventType($event)"
      />

      @if (state.error()) {
        <div class="load-error" role="alert">
          <p>We couldn't load this week's activity. Try again.</p>
          <button type="button" (click)="state.reload()">Try again</button>
        </div>
      } @else if (state.report(); as report) {
        @if (isEmptyAccount(report)) {
          <p class="empty-account">No activity recorded for this account yet.</p>
        } @else {
          <app-account-summary [report]="report" />
          <app-location-table [locations]="report.locations" [minimumEligibleWeeks]="report.minimumEligibleWeeks" />
        }

        <footer class="footnote">
          <ul>
            <li>Compared with the last {{ report.baselineWeeks }} full weeks at this location</li>
            <li>Inbound events, not unique customers</li>
            <li>Exact duplicates counted once</li>
            <li>Locations that usually get 2 or fewer events a week can't show 'lower than usual'</li>
            @if (report.eventType !== 'all') {
              <li>Per-type counts at a single location are small; only large changes show up.</li>
            }
            @if (dataAsOfLabel(); as dataAsOf) {
              <li>Data as of {{ dataAsOf }}</li>
            }
          </ul>
        </footer>
      } @else {
        <p class="loading" role="status">Loading…</p>
      }
    </main>
  `,
  styles: `
    main { max-width: 60rem; margin: 0 auto; padding: 1.5rem; font-family: system-ui, sans-serif; }
    app-dashboard-filters { margin-bottom: 1.5rem; }
    app-account-summary { margin-bottom: 1.5rem; }
    .footnote { margin-top: 1.5rem; color: #555; font-size: 0.875rem; }
    .footnote ul { padding-left: 1.25rem; }
    .load-error { display: flex; gap: 1rem; align-items: center; }
  `,
})
export class DashboardPage {
  protected readonly state = inject(DashboardState);

  protected readonly lastLoadedReport = linkedSignal<ActivityHealthReport | undefined, ActivityHealthReport | undefined>({
    source: this.state.report,
    computation: (report, previous) => report ?? previous?.value,
  });

  protected readonly selectedWeekRange = computed<WeekRange | null>(() => {
    const report = this.state.report();
    const week = this.state.week();
    if (report !== undefined) {
      return report.week;
    }
    return week === null ? null : { start: week, end: sundayOfWeek(week) };
  });

  protected readonly stepperWeek = computed<WeekRange | null>(() => {
    const boundsReport = this.lastLoadedReport();
    return boundsReport === undefined ? null : (this.selectedWeekRange() ?? boundsReport.week);
  });

  protected readonly dataAsOfLabel = computed(() => {
    const report = this.state.report();
    return report?.dataAsOf ? formatCalendarDay(report.dataAsOf, report.account.timezone) : null;
  });

  protected isEmptyAccount(report: ActivityHealthReport): boolean {
    return report.locations.length === 0 && report.summary.baseline.weeksUsed === 0;
  }
}
import { ChangeDetectionStrategy, Component, computed, input, output } from '@angular/core';
import { Account, EVENT_TYPES, EventType, WeekRange } from '../../../core/models';
import { isEventType } from '../event-type-guard';
import { EVENT_TYPE_LABELS } from '../health-copy';
import { addWeeks, formatWeekRange } from '../week';

@Component({
  selector: 'app-dashboard-filters',
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <label class="filter">
      Viewing as
      <select (change)="onAccountChange($event)">
        @for (account of accounts(); track account.id) {
          <option [value]="account.id" [selected]="account.id === accountId()">{{ account.name }}</option>
        }
      </select>
    </label>

    @if (weekStepper(); as stepper) {
      <div class="week-stepper" role="group" aria-label="Week">
        <button type="button" [disabled]="!stepper.canGoToPreviousWeek" (click)="stepWeek(stepper.weekStart, -1)">◀ Previous week</button>
        <span class="week-label" aria-live="polite">{{ stepper.weekLabel }}</span>
        <button type="button" [disabled]="!stepper.canGoToNextWeek" (click)="stepWeek(stepper.weekStart, 1)">Next week ▶</button>
      </div>
    }

    <label class="filter">
      Activity type
      <select (change)="onEventTypeChange($event)">
        @for (option of eventTypeOptions; track option.value) {
          <option [value]="option.value" [selected]="option.value === eventType()">{{ option.label }}</option>
        }
      </select>
    </label>
  `,
  styles: `
    :host { display: flex; flex-wrap: wrap; gap: 1rem 2rem; align-items: center; }
    .filter { display: flex; gap: 0.5rem; align-items: center; }
    .week-stepper { display: flex; gap: 0.75rem; align-items: center; }
    .week-label { min-width: 16rem; text-align: center; font-weight: 600; }
  `,
})
export class DashboardFilters {
  readonly accounts = input.required<readonly Account[]>();
  readonly accountId = input.required<number>();
  readonly week = input<WeekRange | null>(null);
  readonly earliestWeek = input<string | null>(null);
  readonly latestCompleteWeek = input<string | null>(null);
  readonly eventType = input.required<EventType>();

  readonly accountSelected = output<number>();
  readonly weekSelected = output<string>();
  readonly eventTypeSelected = output<EventType>();

  protected readonly eventTypeOptions = EVENT_TYPES.map((value) => ({ value, label: EVENT_TYPE_LABELS[value] }));
  protected readonly weekStepper = computed(() => {
    const week = this.week();
    const earliestWeek = this.earliestWeek();
    const latestCompleteWeek = this.latestCompleteWeek();
    if (week === null || earliestWeek === null || latestCompleteWeek === null) {
      return null;
    }
    return {
      weekStart: week.start,
      weekLabel: formatWeekRange(week.start, week.end),
      canGoToPreviousWeek: week.start > earliestWeek,
      canGoToNextWeek: week.start < latestCompleteWeek,
    };
  });

  protected onAccountChange(event: Event): void {
    this.accountSelected.emit(Number((event.target as HTMLSelectElement).value));
  }

  protected onEventTypeChange(event: Event): void {
    const selectedValue = (event.target as HTMLSelectElement).value;
    if (isEventType(selectedValue)) {
      this.eventTypeSelected.emit(selectedValue);
    }
  }

  protected stepWeek(weekStart: string, weekCount: number): void {
    this.weekSelected.emit(addWeeks(weekStart, weekCount));
  }
}
import { ChangeDetectionStrategy, Component, input, output } from '@angular/core';
import { WeekRange } from '../../../core/models';

@Component({
  selector: 'app-week-picker',
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: '',
})
export class WeekPicker {
  readonly week = input.required<WeekRange>();
  readonly earliestWeek = input.required<string>();
  readonly latestCompleteWeek = input.required<string>();

  readonly weekSelected = output<string>();
}
import { ChangeDetectionStrategy, Component, computed, input } from '@angular/core';
import { ActivityHealthReport } from '../../../core/models';
import { activityCount, statusLabel, usualRange } from '../health-copy';

@Component({
  selector: 'app-account-summary',
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <h2>{{ report().account.name }} — all locations</h2>
    <p class="method">Compared with the last {{ report().baselineWeeks }} full weeks for this account</p>
    <p class="count">
      @if (range(); as usual) {
        {{ countText() }} · usually {{ usual }} a week
      } @else {
        {{ countText() }}
      }
    </p>
    <p class="status" [attr.data-status]="report().summary.status">{{ status() }}</p>
  `,
  styles: `
    :host { display: block; }
    .method { color: #555; margin-top: 0; }
    .count { font-size: 1.5rem; margin: 0.5rem 0; }
    .status { font-weight: 600; }
    .status[data-status='above'] { color: #9a3412; }
    .status[data-status='below'] { color: #1e40af; }
  `,
})
export class AccountSummary {
  readonly report = input.required<ActivityHealthReport>();

  protected readonly countText = computed(() => activityCount(this.report().summary.count, this.report().eventType));
  protected readonly range = computed(() => usualRange(this.report().summary));
  protected readonly status = computed(() => statusLabel(this.report().summary, this.report().minimumEligibleWeeks));
}
import { ChangeDetectionStrategy, Component, computed, input } from '@angular/core';
import { LocationHealth } from '../../../core/models';
import { statusLabel, usualRange } from '../health-copy';

@Component({
  selector: 'app-location-table',
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <table>
      <thead>
        <tr>
          <th scope="col">Location</th>
          <th scope="col" class="number">Events</th>
          <th scope="col">Usual range</th>
          <th scope="col">Status</th>
        </tr>
      </thead>
      <tbody>
        @for (row of rows(); track row.location) {
          <tr>
            <th scope="row">{{ row.location }}</th>
            <td class="number">{{ row.count }}</td>
            <td>
              @if (row.range; as usual) {
                Usually {{ usual }} a week
              }
            </td>
            <td [attr.data-status]="row.status">{{ row.statusText }}</td>
