async function afterScheduledFocus(fixture: ComponentFixture<WeekPicker>): Promise<void> {
  for (let round = 0; round < 3; round++) {
    await new Promise<void>((resolve) => setTimeout(resolve, 0));
    await fixture.whenStable();
