const { chromium } = require('/Users/josemejia/Documents/Software Development/Qualitara/relay-activity-health/.claude/worktrees/agent-af1bc63b76d53c82b/web/node_modules/playwright');

const baseUrl = 'http://localhost:4300';
const outputDirectory = '/private/tmp/claude-501/-Users-josemejia-Documents-Software-Development-Qualitara-relay-activity-health/74b25094-c0f6-4b4a-a9ba-66244c7b622d/scratchpad/implemented';
const only = process.argv[2];

async function settledPage(browser) {
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  return page;
}

async function shoot(browser, name, url) {
  if (only && only !== name) return;
  const page = await settledPage(browser);
  await page.goto(baseUrl + url);
  await page.waitForSelector('app-account-summary, .empty-account, [role="alert"]');
  await page.waitForTimeout(300);
  await page.screenshot({ path: `${outputDirectory}/${name}.png`, fullPage: true });
  console.log(name, page.url());
  await page.close();
}

(async () => {
  const browser = await chromium.launch();
  await shoot(browser, 'account-14-2026-07-20', '/dashboard?account=14&week=2026-07-20&type=all');
  await shoot(browser, 'account-6-2026-06-01', '/dashboard?account=6&week=2026-06-01&type=all');
  await shoot(browser, 'account-6-2026-06-08', '/dashboard?account=6&week=2026-06-08&type=all');
  await shoot(browser, 'account-8-2026-03-02', '/dashboard?account=8&week=2026-03-02&type=all');
  await shoot(browser, 'account-14-2026-02-02', '/dashboard?account=14&week=2026-02-02&type=all');
  await shoot(browser, 'account-20', '/dashboard?account=20');

  if (!only || only === 'picker-open') {
    const page = await settledPage(browser);
    await page.goto(baseUrl + '/dashboard?account=14&week=2026-07-20&type=all');
    await page.waitForSelector('app-account-summary');
    await page.getByRole('button', { name: 'Mon Jul 20 – Sun Jul 26, 2026, choose week' }).focus();
    await page.keyboard.press('Enter');
    await page.waitForSelector('[role="dialog"]');
    await page.waitForTimeout(300);
    await page.keyboard.press('ArrowUp');
    await page.waitForTimeout(200);
    await page.screenshot({ path: `${outputDirectory}/picker-open.png` });
    const focusedLabel = await page.evaluate(() => document.activeElement?.getAttribute('aria-label'));
    console.log('picker-open focused', focusedLabel);
    await page.keyboard.press('Enter');
    await page.waitForTimeout(500);
    console.log('picker-open after Enter', page.url(), await page.evaluate(() => document.activeElement?.getAttribute('aria-label')));
    await page.close();
  }

  if (!only || only === 'loading') {
    const page = await settledPage(browser);
    await page.route('**/api/accounts/*/activity-health**', () => new Promise(() => {}));
    await page.goto(baseUrl + '/dashboard?account=14&week=2026-07-20&type=all');
    await page.waitForSelector('[role="status"]');
    await page.waitForTimeout(300);
    await page.screenshot({ path: `${outputDirectory}/loading.png`, fullPage: true });
    console.log('loading');
    await page.close();
  }

  if (!only || only === 'error') {
    const page = await settledPage(browser);
    await page.goto(baseUrl + '/dashboard?account=14&week=2026-07-20&type=all');
    await page.waitForSelector('app-account-summary');
    await page.route('**/api/accounts/*/activity-health**', (route) => route.fulfill({ status: 500, contentType: 'application/problem+json', body: '{"title":"boom","status":500}' }));
    await page.getByRole('button', { name: '◀ Previous week' }).click();
    await page.waitForSelector('[role="alert"]');
    await page.waitForTimeout(300);
    await page.screenshot({ path: `${outputDirectory}/error-after-week-change.png`, fullPage: true });
    await page.close();

    const firstLoad = await settledPage(browser);
    await firstLoad.route('**/api/accounts/*/activity-health**', (route) => route.fulfill({ status: 500, contentType: 'application/problem+json', body: '{"title":"boom","status":500}' }));
    await firstLoad.goto(baseUrl + '/dashboard?account=14&week=2026-07-20&type=all');
    await firstLoad.waitForSelector('[role="alert"]');
    await firstLoad.waitForTimeout(300);
    await firstLoad.screenshot({ path: `${outputDirectory}/error-first-load.png`, fullPage: true });
    console.log('error');
    await firstLoad.close();
  }

  await browser.close();
})();

